import {fuelMetrics,fraction,monthBounds,filledTravel,previousMonthRecord,validFuel} from './fuel.mjs';
import {session,storageKey,api,logout} from './session.mjs';
import {directoryFields,validDirectory,migrateDirectories,applyContact} from './contacts.mjs';
import {travelTemplate} from './travel-template.mjs';
import {eventDates,validDate,costTotal,travelCalc,round} from './calc.mjs';
const $=s=>document.querySelector(s), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=n=>Number(n).toLocaleString('uk-UA',{minimumFractionDigits:2,maximumFractionDigits:2}),num=n=>Number(n).toLocaleString('uk-UA',{maximumFractionDigits:2});
const today=()=>new Intl.DateTimeFormat('en-CA',{timeZone:'Europe/Kyiv',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());
const date=s=>s?new Date(s+'T12:00:00').toLocaleDateString('uk-UA'):'__________';
const longDate=s=>{if(!s)return '________________';const d=new Date(s+'T12:00:00');return `«${String(d.getDate()).padStart(2,'0')}» ${['січня','лютого','березня','квітня','травня','червня','липня','серпня','вересня','жовтня','листопада','грудня'][d.getMonth()]} ${d.getFullYear()} року`};
const defaults=()=>({version:1,event:{venue:'',date:today(),receiptDate:'',number:'',city:'Київ',person:'',products:['Дона'],items:['Чай','Кава','Цукерки','Печиво'].map(name=>({name,qty:1,price:0}))},profile:{company:'«МЕДА Фармасьютікалз Світселенд ГмБх»',head:'В. С. Піонт',budgetHead:'Піонт В.С.',position:'Голова представництва'},products:['Дона','Целебрекс','Лірика','Алдара','Елідел'],travel:{liters:0,rate:10,startFuel:20,endTarget:20,adjustmentKm:0,refill:0,odometer:12675.7,basis:'seat · вересень 2026 · D21/F21/G21',driver:'',car:'SEAT',plate:'',from:today(),to:today(),rows:[{date:today(),route:'',km:0}]},archive:[]});
let state=defaults(),storageOK=true,view='home',docType='order',deferredInstall,contactKind='clinics';
try{const saved=JSON.parse(localStorage.getItem(storageKey)||(session.user.role==='admin'?localStorage.getItem('zvit-v1'):null));if(saved&&saved.version===1&&saved.event&&saved.travel&&Array.isArray(saved.archive))state={...state,...saved,profile:{...state.profile,...saved.profile}}}catch{storageOK=false}
migrateDirectories(state);
state.travel.endTarget ??= state.travel.startFuel;state.travel.adjustmentKm ??= 0;
const parentOf={event:'home',travel:'home',fuel:'travel',contacts:'profile',signer:'profile',accounts:'profile',password:'profile'};
const rootOf=v=>parentOf[v]?rootOf(parentOf[v]):v;
function save(){try{localStorage.setItem(storageKey,JSON.stringify(state));storageOK=true}catch{storageOK=false}}
function toast(msg){$('#toast').textContent=msg;$('#toast').classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('show'),4000)}

/* ---------- Іконки ---------- */
const P={home:'M3 10.5 12 3l9 7.5V20a1 1 0 0 1-1 1h-5v-6H9v6H4a1 1 0 0 1-1-1z',doc:'M7 3h7l5 5v12a1 1 0 0 1-1 1H7a1 1 0 0 1-1-1V4a1 1 0 0 1 1-1zM14 3v5h5M9 13h6M9 17h6',car:'M5 17h14M6 17v2M18 17v2M4 13l2-6h12l2 6v4H4zM7.5 14.5h.01M16.5 14.5h.01',list:'M8 6h12M8 12h12M8 18h12M4 6h.01M4 12h.01M4 18h.01',user:'M12 12a4 4 0 1 0 0-8 4 4 0 0 0 0 8zM4 21a8 8 0 0 1 16 0',users:'M9 11a4 4 0 1 0 0-8 4 4 0 0 0 0 8zM2 21a7 7 0 0 1 14 0M16 3.5a4 4 0 0 1 0 7M18 14a6 6 0 0 1 4 7',right:'m9 6 6 6-6 6',left:'m15 5-7 7 7 7',plus:'M12 5v14M5 12h14',print:'M7 9V3h10v6M7 17H4v-7h16v7h-3M7 14h10v7H7z',eye:'M2 12s3.5-7 10-7 10 7 10 7-3.5 7-10 7S2 12 2 12zM12 15a3 3 0 1 0 0-6 3 3 0 0 0 0 6z',save:'M6 3h12v18l-6-4-6 4z',download:'M12 4v11M7 10l5 5 5-5M5 20h14',upload:'M12 20V9M7 14l5-5 5 5M5 4h14',phone:'M8 2h8a1 1 0 0 1 1 1v18a1 1 0 0 1-1 1H8a1 1 0 0 1-1-1V3a1 1 0 0 1 1-1zM11 18h2',x:'M6 6l12 12M18 6 6 18',building:'M4 21V5a1 1 0 0 1 1-1h9a1 1 0 0 1 1 1v16M15 9h4a1 1 0 0 1 1 1v11M3 21h18M8 8h3M8 12h3M8 16h3',pen:'M4 20h4L19 9l-4-4L4 16zM13 7l4 4',search:'M11 18a7 7 0 1 0 0-14 7 7 0 0 0 0 14zM20 20l-4-4',next:'M5 12h14M13 6l6 6-6 6',check:'M5 12.5l4.5 4.5L19 7',chart:'M4 20V10M10 20V4M16 20v-7M22 20H2',fuel:'M4 21V5a2 2 0 0 1 2-2h6a2 2 0 0 1 2 2v16M3 21h12M14 10h2a2 2 0 0 1 2 2v4a1.5 1.5 0 0 0 3 0V8l-3-3M7 8h4',back:'M3 12a9 9 0 1 0 3-6.7M3 4v5h5',key:'M15 7a4 4 0 1 0-3.5 5.9L10 14.5V17H7.5v2.5H5V21H2v-3l7.1-7.1A4 4 0 0 0 15 7zM16 6h.01',logout:'M15 4h3a2 2 0 0 1 2 2v12a2 2 0 0 1-2 2h-3M10 17l5-5-5-5M15 12H3'};
const icon=(n,c='')=>`<svg class="ic ${c}" viewBox="0 0 24 24" aria-hidden="true"><path d="${P[n]}"/></svg>`;

/* ---------- Будівельні блоки ---------- */
function field(label,key,value,type='text',extra=''){return `<label class="field"><span>${label}</span><input type="${type}" data-key="${key}" value="${esc(value)}" ${extra}></label>`}
const btn=(text,action,cls='button')=>`<button class="${cls}" data-action="${action}">${text}</button>`;
const group=(title,body,cls='')=>`<section class="group ${cls}">${title?`<h2 class="group-title">${title}</h2>`:''}<div class="card">${body}</div></section>`;
const row=(ic,title,sub,action,extra='')=>`<button class="row" data-action="${action}" ${extra}><span class="avatar">${icon(ic)}</span><span class="row-main"><b>${title}</b>${sub?`<small>${sub}</small>`:''}</span>${icon('right','chev')}</button>`;
const quick=(...a)=>`<div class="quick">${a.map(([ic,label,action])=>`<button data-action="${action}"><span class="q-icon">${icon(ic)}</span><span>${label}</span></button>`).join('')}</div>`;
const plural=(n,one,few,many)=>{const m10=n%10,m100=n%100;return `${n} ${m10===1&&m100!==11?one:m10>=2&&m10<=4&&(m100<12||m100>14)?few:many}`};
const monthName=s=>{if(!s)return '';const d=new Date(s.slice(0,7)+'-15T12:00:00');return d.toLocaleDateString('uk-UA',{month:'long',year:'numeric'})};

/* ---------- Головна ---------- */
function homeView(){
 const e=state.event,t=state.travel,r=travelCalc(t),recent=state.archive.slice(-4).reverse();
 return {body:`<header class="large-title"><div><small>${esc(session.user.name)}</small><h1>Документи</h1></div><button class="round" data-view="profile" aria-label="Профіль">${icon('user')}</button></header>
 <div class="tiles">
  <button class="tile dark" data-view="event"><span class="tile-icon">${icon('doc')}</span><span class="tile-text"><b>Круглий стіл</b><small>${e.venue?esc(e.venue):'Наказ + кошторис'}</small></span><span class="tile-amount">${money(costTotal(e.items))} ₴</span></button>
  <button class="tile" data-view="travel"><span class="tile-icon">${icon('car')}</span><span class="tile-text"><b>Подорожній лист</b><small>${esc(monthName(t.from))}</small></span><span class="tile-amount">${r.error||r.total===undefined?'—':num(r.total)+' км'}</span></button>
 </div>
 <section class="group"><div class="group-head"><h2 class="group-title">Останні звіти</h2>${state.archive.length?`<button class="link" data-view="archive">Усі</button>`:''}</div>
 ${recent.length?`<div class="card">${recent.map(archiveRow).join('')}</div>`:`<div class="card empty">${icon('list','big')}<b>Тут з’являться збережені звіти</b><p>Заповніть документ і натисніть «Зберегти».</p></div>`}</section>`};
}

/* ---------- Круглий стіл ---------- */
function eventView(){const e=state.event;return {title:'Круглий стіл',
 body:`<section class="hero"><span class="hero-label">Кошторис події</span><div class="hero-amount" id="budget-total"></div><div class="hero-status" id="preview-status"></div></section>${quick(['eye','Перегляд','preview'],['save','В архів','save-event'],['x','Очистити','new-event'],['building','Довідники','manage-contacts'])}
 ${group('Клініка',`${contactPicker('clinics')}${field('Назва закладу','event.venue',e.venue,'text','placeholder="Наприклад, МЦ Леодерм" maxlength="180"')}${field('Місто','event.city',e.city,'text','maxlength="80"')}<div class="card-foot" id="remember-clinics">${btn(icon('save')+'Додати цю клініку в довідник','remember-clinic','link')}</div>`)}
 ${group('Дати',`<div class="field-grid">${field('Круглий стіл','event.date',e.date,'date','required')}${field('Дата чеку','event.receiptDate',e.receiptDate||'','date','required')}</div>${field('Номер наказу','event.number',e.number,'text','placeholder="24/11" maxlength="40"')}<p class="hint" id="order-date"></p>`)}
 ${group('Відповідальна особа',`${contactPicker('representatives')}${field('ПІБ у давальному відмінку','event.person',e.person,'text','placeholder="Кузьмінській Уляні Іванівні" maxlength="180"')}<div class="card-foot" id="remember-representatives">${btn(icon('save')+'Додати цю особу в довідник','remember-representative','link')}</div>`)}
 ${group('Препарати',`<div class="chips">${state.products.map(p=>`<button class="chip ${e.products.includes(p)?'checked':''}" data-product="${esc(p)}" aria-pressed="${e.products.includes(p)}">${e.products.includes(p)?icon('check'):''}${esc(p)}</button>`).join('')}</div><div class="inline-add"><input id="new-product" placeholder="Інший препарат" aria-label="Назва нового препарату" maxlength="80"><button class="round soft" data-action="add-product" aria-label="Додати препарат">${icon('plus')}</button></div>`)}
 ${group('Витрати',`<div class="budget-rows">${e.items.map((r,i)=>`<div class="budget-row"><input class="b-name" aria-label="Позиція ${i+1}" placeholder="Назва позиції" data-item="${i}" data-prop="name" value="${esc(r.name)}" maxlength="120"><button class="icon-btn" data-remove-item="${i}" aria-label="Видалити позицію ${i+1}">${icon('x')}</button><label class="mini"><span>К-сть</span><input data-item="${i}" data-prop="qty" type="number" inputmode="decimal" min="0.01" step="0.01" value="${r.qty}" aria-label="Кількість ${i+1}"></label><label class="mini"><span>Ціна, ₴</span><input data-item="${i}" data-prop="price" type="number" inputmode="decimal" min="0" step="0.01" value="${r.price}" aria-label="Ціна ${i+1}"></label><b class="b-total" data-line-total="${i}"></b></div>`).join('')}</div><button class="add-row" data-action="add-item">${icon('plus')}Додати позицію</button>`)}`,
 bar:`<button class="button pill" data-action="print-both">${icon('print')}Друкувати наказ і кошторис</button>`}}

/* ---------- Подорожній лист ---------- */
let fuelRows=[],fuelLoaded=false;
function prepareMonthly(){const t=state.travel;if(t.fuelMode!=='filled'){t.refill=travelCalc(t).refill??0;t.fuelMode='filled';}const bounds=monthBounds(t.from?.slice(0,7));if(bounds){Object.assign(t,bounds);t.rows.forEach(row=>{if(row.date<t.from||row.date>t.to)row.date=t.from;});}Object.assign(t,filledTravel(t));}
function previousLine(){const row=previousMonthRecord(fuelRows,state.travel);if(!row)return `<p class="hint">${fuelLoaded?'Запису за попередній місяць для цього авто немає. Залишок і одометр введіть у «Початкових даних».':'Завантажуємо попередній місяць…'}</p>`;const r=fuelMetrics(row);const t=state.travel,same=Math.abs(Number(t.startFuel)-r.endFuel)<0.01&&Math.abs(Number(t.odometer)-r.endOdo)<0.01;return same?`<p class="hint">Залишок і одометр на виїзді взято з попереднього місяця (${esc(monthName(row.from))}).</p>`:`<p class="hint">У попередньому місяці на приїзді було ${num(r.endFuel)} л і ${num(r.endOdo)} км, а тут введено інше.</p><div class="card-foot">${btn(icon('back')+'Взяти з попереднього місяця','fuel-previous','link')}</div>`}
function tankMax(){const t=state.travel;return Math.max(1,Math.ceil(Number(t.startFuel||0)+Number(t.refill||0)),Math.ceil(Number(t.endTarget||0)))}
function setMonth(month){const bounds=monthBounds(month);if(!bounds)return toast('Виберіть коректний місяць.');Object.assign(state.travel,bounds);state.travel.rows.forEach(row=>row.date=bounds.from);state.travel.refill=0;state.travel.realKm='';state.travel.adjustmentKm=0;delete state.travel.autoBasisMonth;return previousFuel().then(()=>{save();render()})}
const shiftMonth=(from,d)=>{const x=new Date(from.slice(0,7)+'-15T12:00:00Z');x.setUTCMonth(x.getUTCMonth()+d);return x.toISOString().slice(0,7)};
function travelView(){prepareMonthly();if(!fuelLoaded)loadFuel().then(ok=>{if(ok&&view==='travel'){const row=previousMonthRecord(fuelRows,state.travel);if(row&&state.travel.refill===0&&!state.travel.autoBasisMonth){const result=travelCalc(row);Object.assign(state.travel,{odometer:result.endOdo,startFuel:result.endFuel,endTarget:result.endFuel,rate:row.rate,autoBasisMonth:state.travel.from.slice(0,7),basis:'попередній місяць '+row.from.slice(0,7)});Object.assign(state.travel,filledTravel(state.travel));}render();}});
 const t=state.travel,car=t.car.trim().toUpperCase();return {title:'Пальне за місяць',
 body:`<section class="hero fuel-hero"><div class="month-switch"><button class="round glass" data-action="month-prev" aria-label="Попередній місяць">${icon('left')}</button><b>${esc(monthName(t.from).replace(/ р\.$/,''))}</b><button class="round glass" data-action="month-next" aria-label="Наступний місяць">${icon('right')}</button></div><div class="car-switch">${btn('SEAT','preset-seat','chip glass'+(car==='SEAT'?' on':''))}${btn('VW','preset-vw','chip glass'+(car==='VW'?' on':''))}${car&&car!=='SEAT'&&car!=='VW'?`<span class="chip glass on">${esc(t.car)}</span>`:''}</div><span class="hero-label">Очікуваний пробіг</span><div class="hero-amount" id="km-total"></div><div class="hero-status" id="fuel-status"></div></section>
 <section class="fuel-input"><label for="refill-input">Залито за місяць</label><div class="amount-input"><input id="refill-input" type="number" inputmode="decimal" min="0" step="0.01" data-key="travel.refill" value="${esc(t.refill||'')}" style="width:${String(t.refill||'0').length+.6}ch" placeholder="0"><span>л</span></div></section>
 <section class="fuel-input tank"><div class="tank-head"><label for="tank-range">У баку по приїзді</label><b id="tank-value"></b></div><div class="tank-row"><button class="round soft" data-action="tank-minus" aria-label="Менше на 1 л">−</button><input id="tank-range" type="range" min="0" max="${tankMax()}" step="0.5" data-key="travel.endTarget" value="${esc(t.endTarget)}"><button class="round soft" data-action="tank-plus" aria-label="Більше на 1 л">+</button></div><p class="hint center" id="tank-hint"></p></section>
 ${quick(['eye','Перегляд','travel-preview'],['next','Новий місяць','next-period'],['chart','Аналітика','fuel-analytics'],['save','В архів','save-travel'])}
 ${group('Розраховано',`<div class="stat-grid" id="fuel-stats"></div>${previousLine()}`)}
 <details class="group more"><summary>Початкові дані</summary><div class="card"><div class="field-grid">${field('Залишок на виїзді, л','travel.startFuel',t.startFuel,'number','min="0" step="0.01" inputmode="decimal"')}${field('Одометр на виїзді, км','travel.odometer',t.odometer,'number','min="0" step="0.01" inputmode="decimal"')}${field('Норма, л/100 км','travel.rate',t.rate,'number','min="0.01" step="0.01" inputmode="decimal"')}${field('Поправка, ± км','travel.adjustmentKm',t.adjustmentKm,'number','step="0.1"')}</div><div class="card-foot">${btn(icon('back')+'Підтягнути з попереднього місяця','fuel-previous','link')}</div></div></details>
 <details class="group more"><summary>Водій і автомобіль${t.driver?` · ${esc(t.driver)}`:''}</summary><div class="card">${contactPicker('representatives','travel')}${field('Водій','travel.driver',t.driver,'text','maxlength="180"')}<div class="field-grid">${field('Автомобіль','travel.car',t.car,'text','maxlength="120"')}${field('Держномер','travel.plate',t.plate,'text','maxlength="30"')}</div></div></details>
 <details class="group more"><summary>Поїздки · ${plural(t.rows.length,'рядок','рядки','рядків')}</summary><div class="card"><div id="trip-rows">${tripRows()}</div><button class="add-row" data-action="add-trip">${icon('plus')}Додати поїздку</button>${t.rows.length>1?`<div class="card-foot">${btn('Розподілити порівну','split-trips','link')}</div>`:''}</div></details>
 <details class="group more"><summary>Реальний пробіг · для аналізу</summary><div class="card">${field('За період, км','travel.realKm',t.realKm??'','number','min="0" step="0.1" inputmode="decimal"')}<div id="real-comparison"></div></div></details>
 <details class="group more"><summary>Реквізити бланка</summary><div class="card"><div class="field-grid">${field('Номер листа','travel.number',t.number||'','text','maxlength="30"')}${field('Режим роботи','travel.workMode',t.workMode||'','text','maxlength="80"')}${field('Марка пального','travel.fuelBrand',t.fuelBrand||'','text','maxlength="30"')}${field('Код марки','travel.fuelCode',t.fuelCode||'','text','maxlength="20"')}${field('Час виїзду','travel.departTime',t.departTime||'','time')}${field('Час повернення','travel.returnTime',t.returnTime||'','time')}${field('Годин у наряді','travel.hours',t.hours||'','number','min="0" step="0.1"')}${field('Колона','travel.column',t.column||'','text','maxlength="30"')}${field('Бригада','travel.brigade',t.brigade||'','text','maxlength="30"')}</div>${field('Особливі відмітки','travel.notes',t.notes||'','text','maxlength="300"')}</div></details>`,
 bar:`<div class="bar-2"><button class="button secondary" data-action="save-month">${icon('save')}Зберегти</button><button class="button" data-action="print-travel">${icon('print')}Друк</button></div>`}}
function tripRows(){const result=travelCalc(state.travel);return state.travel.rows.map((r,i)=>{const last=i===state.travel.rows.length-1;return `<div class="trip"><div class="trip-top"><b>Поїздка ${i+1}</b>${last&&state.travel.rows.length>1?'<span class="tag">решта пробігу</span>':''}<button class="icon-btn" data-remove-trip="${i}" aria-label="Видалити поїздку ${i+1}" ${state.travel.rows.length===1?'disabled':''}>${icon('x')}</button></div><input aria-label="Маршрут поїздки ${i+1}" placeholder="Маршрут: звідки → куди" data-trip="${i}" data-prop="route" value="${esc(r.route)}" maxlength="200"><div class="field-grid"><label class="field"><span>Дата</span><input type="date" data-trip="${i}" data-prop="date" value="${esc(r.date)}"></label><label class="field"><span>Пробіг, км</span><div class="stepper">${last?'':`<button data-step-trip="${i}" data-step="-1" aria-label="Зменшити пробіг поїздки ${i+1}">−</button>`}<input type="number" min="0" step="0.01" inputmode="decimal" aria-label="Пробіг поїздки ${i+1}" data-trip="${i}" data-prop="km" value="${last?result.rows?.[i]?.km??0:r.km}" ${last?'readonly data-last-km':''}>${last?'':`<button data-step-trip="${i}" data-step="1" aria-label="Збільшити пробіг поїздки ${i+1}">+</button>`}</div></label></div></div>`}).join('')}

/* ---------- Аналітика пального ---------- */
function fuelView(){const rows=fuelRows.slice().sort((a,b)=>b.from.localeCompare(a.from)||a.car.localeCompare(b.car));
 return {title:'Аналітика пального',right:`<button class="round ghost" data-action="fuel-analytics" aria-label="Оновити">${icon('back')}</button>`,body:`<p class="foot-note top">Записи зберігаються на сервері для вашого облікового запису. Торкніться місяця, щоб відкрити його.</p>
 ${session.user.role==='admin'?`<section class="group"><div class="card">${row('upload','Імпортувати історію','З Excel і зразка, без заміни наявних записів','fuel-import')}</div></section>`:''}
 ${rows.length?[...new Set(rows.map(t=>t.from.slice(0,4)))].map(y=>`<section class="group"><h2 class="group-title">${y}</h2><div class="card">${rows.filter(t=>t.from.startsWith(y)).map(t=>{const r=fuelMetrics(t);return `<button class="row" data-action="fuel-open" data-index="${fuelRows.indexOf(t)}"><span class="avatar travel">${icon('fuel')}</span><span class="row-main"><b>${esc(new Date(t.from.slice(0,7)+'-15T12:00:00').toLocaleDateString('uk-UA',{month:'long'}))} · ${esc(t.car)} ${esc(t.plate)}</b><small>${num(r.total)} км · залито ${num(r.refill)} л · ${fraction(r.actualRate,t.liters)} · відх. ${num(r.deviation)}%${r.realKm===null?'':` · реальний ${num(r.realKm)} км`}</small></span>${icon('right','chev')}</button>`}).join('')}</div></section>`).join(''):`<section class="group"><div class="card empty">${icon('chart','big')}<b>Поки немає записів</b><p>Збережіть місяць у подорожньому листі.</p></div></section>`}`}}

/* ---------- Звіти ---------- */
function archiveRow(r){return `<div class="row-wrap"><button class="row" data-action="open-${r.id}"><span class="avatar ${r.type}">${icon(r.type==='event'?'doc':'car')}</span><span class="row-main"><b>${esc(r.title)}</b><small>${r.type==='event'?'Наказ + кошторис':'Подорожній лист'} · ${date(r.date)}</small></span></button><button class="icon-btn" data-delete-archive="${r.id}" aria-label="Видалити звіт ${esc(r.title)}">${icon('x')}</button></div>`}
function archiveList(q){const rows=state.archive.filter(r=>r.title.toLowerCase().includes(q.toLowerCase()));return rows.length?`<div class="card">${rows.slice().reverse().map(archiveRow).join('')}</div>`:`<div class="card empty">${icon(q?'search':'list','big')}<b>${q?'Звітів не знайдено':'Тут будуть ваші звіти'}</b><p>Заповніть документ і натисніть «Зберегти».</p></div>`}
function archiveView(){return {body:`<header class="large-title"><div><small>${plural(state.archive.length,'звіт','звіти','звітів')}</small><h1>Звіти</h1></div></header><label class="search">${icon('search')}<input id="archive-search" type="search" placeholder="Заклад або водій" aria-label="Пошук звіту"></label><section class="group" id="archive-list">${archiveList('')}</section>`}}

/* ---------- Профіль ---------- */
function profileView(){const p=state.profile,u=session.user;return {body:`<header class="large-title"><div><small>${u.role==='admin'?'Адміністратор':'Представник'}</small><h1>Профіль</h1></div></header>
 <section class="group"><div class="card"><div class="account"><span class="avatar big-av">${esc((u.name||'?').trim().charAt(0).toUpperCase())}</span><span class="row-main"><b>${esc(u.name)}</b><small>${esc(u.username)}</small></span></div>${u.role==='admin'?row('users','Користувачі','Доступ для представників','accounts'):''}${row('key','Змінити пароль','Від 12 символів','open-password')}</div></section>
 ${group('Довідники',row('building','Клініки',plural(state.clinics.length,'запис','записи','записів'),'contacts-clinics')+row('user','Представники',plural(state.representatives.length,'запис','записи','записів'),'contacts-representatives'))}
 ${group('Документи',row('pen','Підписант',esc(p.head+' · '+p.position),'open-signer'))}
 ${group('Дані',row('download','Завантажити резервну копію','JSON-файл зі звітами й довідниками','backup')+row('upload','Відновити з копії','Замінить поточні дані','restore')+row('phone','Встановити на телефон','Іконка на головному екрані','install'))}
 <section class="group"><div class="card">${`<button class="row danger" data-action="logout"><span class="avatar">${icon('logout')}</span><span class="row-main"><b>Вийти</b></span></button>`}</div></section>
 <p class="foot-note">${storageOK?'Звіти й довідники зберігаються в цьому браузері, місячні записи пального — на сервері. Робіть резервну копію перед зміною пристрою.':'Локальне збереження недоступне. Завантажте резервну копію, щоб не втратити дані.'}</p>`}}
function signerView(){return {title:'Підписант',body:group('',`${field('Організація','profile.company',state.profile.company,'text','maxlength="200"')}${field('Посада','profile.position',state.profile.position,'text','maxlength="120"')}${field('Підпис у наказі','profile.head',state.profile.head,'text','maxlength="100"')}${field('Підпис у кошторисі','profile.budgetHead',state.profile.budgetHead,'text','maxlength="100"')}`)+'<p class="foot-note">Зміни застосовуються до нових документів.</p>'}}
function passwordView(){return {title:'Зміна пароля',body:group('',`<label class="field"><span>Поточний пароль</span><input id="current-password" type="password" autocomplete="current-password" maxlength="256"></label><label class="field"><span>Новий пароль · від 12 символів</span><input id="new-password" type="password" autocomplete="new-password" minlength="12" maxlength="256"></label><label class="field"><span>Повторіть новий пароль</span><input id="repeat-password" type="password" autocomplete="new-password" maxlength="256"></label>`)+'<p class="foot-note">Після зміни пароля потрібно буде увійти знову.</p>',bar:`<button class="button pill" data-action="change-password">Змінити пароль</button>`}}

/* ---------- Користувачі (адміністратор) ---------- */
let accountRows=[];
function accountsView(){if(session.user.role!=='admin')return {title:'Користувачі',body:''};return {title:'Користувачі',right:`<button class="round ghost" data-action="accounts" aria-label="Оновити">${icon('back')}</button>`,body:`
 ${group('Новий представник',`<label class="field"><span>ПІБ</span><input id="account-name" maxlength="180" autocomplete="name"></label><label class="field"><span>Логін · латиниця, цифри, . _ @ -</span><input id="account-username" maxlength="80" autocomplete="off" autocapitalize="none" spellcheck="false"></label><label class="field"><span>Початковий пароль · від 12 символів</span><input id="account-password" type="password" minlength="12" maxlength="256" autocomplete="new-password"></label><p class="hint">Передайте пароль особисто. Представник змінить його в профілі.</p><div class="form-actions single">${btn('Створити обліковий запис','create-account')}</div>`)}
 ${group('Усі користувачі',accountRows.map(r=>`<div class="account-item"><div class="account"><span class="avatar">${icon('user')}</span><span class="row-main"><b>${esc(r.name)}</b><small>${esc(r.username)} · ${r.role==='admin'?'Адміністратор':'Представник'} · ${r.active?'активний':'призупинено'}</small></span>${r.id===session.user.id?'<span class="tag">Це ви</span>':''}</div>${r.id===session.user.id?'':`<div class="account-actions"><button class="chip" data-action="toggle-account" data-id="${esc(r.id)}">${r.active?'Призупинити':'Відновити доступ'}</button><details><summary class="chip">Скинути пароль</summary><div class="inline-add"><input type="password" id="reset-${esc(r.id)}" placeholder="Новий пароль, від 12 символів" autocomplete="new-password" minlength="12" maxlength="256"><button class="button small" data-action="reset-account-password" data-id="${esc(r.id)}">Зберегти</button></div></details></div>`}</div>`).join(''))}`}}
async function showAccounts(){try{const data=await api('/api/users');accountRows=data.users;if(view==='accounts')render();else go('accounts');}catch(e){toast(e.message);}}
async function createAccount(){const button=document.querySelector('[data-action="create-account"]');button.disabled=true;try{await api('/api/users',{name:$('#account-name').value.trim(),username:$('#account-username').value.trim(),password:$('#account-password').value});await showAccounts();toast('Обліковий запис представника створено.');}catch(e){toast(e.message);button.disabled=false;}}
async function editAccount(action,id){try{const body=action==='toggle-account'?{active:!accountRows.find(row=>row.id===id).active}:{password:document.getElementById('reset-'+id).value};await api('/api/users/'+id,body,'PATCH');await showAccounts();toast(action==='toggle-account'?'Доступ оновлено.':'Пароль змінено. Попередні сесії завершено.');}catch(e){toast(e.message);}}
async function changePassword(){const password=$('#new-password').value;if(password!==$('#repeat-password').value)return toast('Нові паролі не збігаються.');try{await api('/api/password',{currentPassword:$('#current-password').value,password});await logout();}catch(e){toast(e.message);}}

/* ---------- Довідники ---------- */
const emptyContact=kind=>Object.fromEntries(directoryFields[kind].map(key=>[key,'']));
const contactDrafts={clinics:emptyContact('clinics'),representatives:emptyContact('representatives')};
const contactForm={clinics:false,representatives:false};
const inDirectory=kind=>{const e=state.event,lc=x=>String(x||'').trim().toLocaleLowerCase('uk');return kind==='clinics'?state.clinics.some(r=>lc(r.name)===lc(e.venue)&&lc(r.city)===lc(e.city)):state.representatives.some(r=>lc(r.person)===lc(e.person))};
function contactPicker(kind,target='event'){
 const clinic=kind==='clinics', current=state[target], rows=state[kind];
 if(!rows.length)return `<div class="picker-empty-wrap"><button class="row picker-empty" data-action="contacts-${kind}"><span class="avatar">${icon(clinic?'building':'user')}</span><span class="row-main"><b>${clinic?'Довідник клінік порожній':'Довідник представників порожній'}</b><small>Додайте запис, щоб потім вибирати його тут</small></span>${icon('right')}</button></div>`;
 const selected=rows.find(r=>r.id===current[clinic?'clinicId':'representativeId']&&(clinic?r.name===current.venue&&r.city===current.city:target==='travel'?r.name===current.driver:r.person===current.person));
 return `<label class="field picker"><span>${target==='travel'?'Водій із представників':'Із довідника'}</span><select data-contact-picker="${kind}" data-target="${target}"><option value="">Ввести вручну</option>${rows.map(r=>`<option value="${esc(r.id)}" ${selected?.id===r.id?'selected':''}>${esc(r.name)}${clinic&&r.city?' · '+esc(r.city):''}</option>`).join('')}</select></label>`;
}
function contactsView(){
 const kind=contactKind,clinic=kind==='clinics',draft=contactDrafts[kind];
 const labels={name:clinic?'Назва клініки':'ПІБ представника',city:'Місто',address:'Адреса',contact:'Контактна особа',phone:'Телефон',person:'ПІБ у давальному відмінку'};
 const form=contactForm[kind]||draft.id?group(draft.id?'Редагування':'Новий запис',`${directoryFields[kind].map(key=>`<label class="field"><span>${labels[key]}</span><input data-directory="${kind}" data-contact-field="${key}" value="${esc(draft[key])}" maxlength="300" type="${key==='phone'?'tel':'text'}"></label>`).join('')}<div class="form-actions">${btn('Скасувати','cancel-'+kind,'button secondary')}${btn(draft.id?'Зберегти':'Додати','save-'+kind)}</div>`):'';
 return {title:'Довідники',body:`<div class="segmented"><button data-ckind="clinics" class="${clinic?'selected':''}">Клініки</button><button data-ckind="representatives" class="${clinic?'':'selected'}">Представники</button></div>
 ${form}
 <section class="group"><div class="card">${form?'':`<button class="add-row top" data-action="add-contact">${icon('plus')}Додати ${clinic?'клініку':'представника'}</button>`}${state[kind].map(r=>`<div class="row-wrap"><button class="row" data-edit-contact="${esc(r.id)}" data-contact-kind="${kind}"><span class="avatar">${icon(clinic?'building':'user')}</span><span class="row-main"><b>${esc(r.name)}</b><small>${[clinic?r.city:r.person,clinic?r.address:'',r.phone].filter(Boolean).map(esc).join(' · ')||'&nbsp;'}</small></span></button><button class="icon-btn" data-remove-contact="${esc(r.id)}" data-contact-kind="${kind}" aria-label="Видалити ${esc(r.name)}">${icon('x')}</button></div>`).join('')}${!state[kind].length&&!form?`<p class="hint pad">${clinic?'Назва й місто клініки підставляються в документи події.':'ПІБ підставляється у наказ і подорожній лист.'}</p>`:''}</div></section>`};
}
function saveContact(kind){
 const draft=contactDrafts[kind],row={id:draft.id||crypto.randomUUID(),...Object.fromEntries(directoryFields[kind].map(k=>[k,draft[k].trim()]))};
 if(!validDirectory([row],kind))return toast(kind==='clinics'?'Введіть назву клініки.':'Введіть ПІБ представника та ПІБ у давальному відмінку.');
 const index=state[kind].findIndex(r=>r.id===row.id);
 if(index<0&&state[kind].length>=500)return toast('У довіднику може бути до 500 записів.');
 if(index<0)state[kind].push(row);else state[kind][index]=row;
 contactDrafts[kind]=emptyContact(kind);contactForm[kind]=false;save();render();toast(storageOK?'Запис збережено.':'Не вдалося зберегти на пристрої. Завантажте резервну копію.');
}
function rememberContact(kind){
 const clinic=kind==='clinics',e=state.event,name=(clinic?e.venue:e.person).trim();
 if(!name)return toast(clinic?'Спочатку введіть назву клініки.':'Спочатку введіть відповідальну особу.');
 if(!clinic){
  const existing=state.representatives.find(r=>r.person.toLocaleLowerCase('uk')===name.toLocaleLowerCase('uk'));
  if(existing){applyContact(state,kind,existing.id);save();render();return toast('Представника вже збережено.');}
  contactDrafts.representatives={...emptyContact(kind),person:name};contactKind='representatives';contactForm.representatives=true;go('contacts');
  document.querySelector('[data-directory="representatives"]')?.focus();
  return toast('Додайте ПІБ у називному відмінку та збережіть запис.');
 }
 const row=state[kind].find(r=>r.name.toLocaleLowerCase('uk')===name.toLocaleLowerCase('uk')&&(!clinic||r.city.trim().toLocaleLowerCase('uk')===e.city.trim().toLocaleLowerCase('uk')));
 if(row){applyContact(state,kind,row.id);save();render();return toast('Такий запис уже збережено. Змінити його можна в довіднику.');}
 if(state[kind].length>=500)return toast('У довіднику може бути до 500 записів.');
 const record={...emptyContact(kind),id:crypto.randomUUID(),name,...(clinic?{city:e.city.trim()}:{person:name})};
 state[kind].push(record);applyContact(state,kind,record.id);save();render();toast(storageOK?'Дані збережено в довіднику.':'Не вдалося зберегти на пристрої. Завантажте резервну копію.');
}

/* ---------- Пальне на сервері ---------- */
async function loadFuel(){try{fuelRows=(await api('/api/fuel')).records;fuelLoaded=true;return true;}catch(e){toast(e.message);return false;}}
async function saveFuel(){prepareMonthly();if(!validFuel(state.travel))throw Error('Перевірте місяць, автомобіль, залиті літри, залишки та пробіг. Витрата має бути більшою за нуль.');await api('/api/fuel',state.travel);await loadFuel();}
async function previousFuel(){if(!await loadFuel())return;prepareMonthly();const t=state.travel,row=previousMonthRecord(fuelRows,t);if(!row){render();return toast('Немає запису за попередній місяць. Початкові дані залишено для ручного введення.');}const r=travelCalc(row);Object.assign(t,{odometer:r.endOdo,startFuel:r.endFuel,endTarget:r.endFuel,rate:row.rate,autoBasisMonth:t.from.slice(0,7),basis:'попередній місяць '+row.from.slice(0,7)});Object.assign(t,filledTravel(t));save();render();}

/* ---------- Рендер ---------- */
const views={home:homeView,event:eventView,travel:travelView,fuel:fuelView,archive:archiveView,profile:profileView,contacts:contactsView,signer:signerView,password:passwordView,accounts:accountsView};
function render(){
 const v=views[view](),pushed=!!parentOf[view];
 document.body.dataset.view=view;document.body.classList.toggle('pushed',pushed);
 $('#appbar').innerHTML=pushed?`<button class="round ghost" data-action="back" aria-label="Назад">${icon('left')}</button><b>${v.title}</b><span class="appbar-right">${v.right||''}</span>`:'';
 $('#content').innerHTML=v.body;
 $('#actionbar').innerHTML=v.bar||'';document.body.classList.toggle('has-bar',!!v.bar);
 const tab=rootOf(view);document.querySelectorAll('.tabbar [data-view]').forEach(el=>{el.classList.toggle('active',el.dataset.view===tab);el.setAttribute('aria-current',el.dataset.view===tab?'page':'false')});
 updateDerived();
}
function go(next){if(next===view)return render();const pushed=!!parentOf[next];view=next;if(next==='travel'){docType='travel';fuelLoaded=false}else if(next==='event')docType='order';pushed?history.pushState({view:next,pushed:true},''):history.replaceState({view:next},'');render();window.scrollTo(0,0)}
function back(){if(history.state?.pushed)history.back();else{view=parentOf[view]||'home';history.replaceState({view},'');render()}}
window.addEventListener('popstate',e=>{if($('#preview-dialog').open)$('#preview-dialog').close();view=e.state?.view||'home';if(view==='travel')docType='travel';render()});
function updateDerived(){
 if(view==='event'){['clinics','representatives'].forEach(k=>{const el=$('#remember-'+k);if(el)el.hidden=!(k==='clinics'?state.event.venue:state.event.person).trim()||inDirectory(k)});const total=$('#budget-total');if(total)total.innerHTML=money(costTotal(state.event.items))+' <small>₴</small>';state.event.items.forEach((r,i)=>{const el=document.querySelector(`[data-line-total="${i}"]`);if(el)el.textContent=money(r.qty*r.price)+' ₴'});const errs=eventErrors(true),st=$('#preview-status');if(st){st.className='hero-status '+(errs.length?'warn':'ok');st.innerHTML=errs.length?'Заповніть: '+esc(errs.join(', ')):icon('check')+'Наказ і кошторис готові до друку'}const od=$('#order-date'),o=eventDates(state.event).orderDate;if(od)od.textContent=o?`Дата наказу й кошторису — ${date(o)}, за день до дати чеку. Ставиться автоматично.`:'Дата наказу ставиться автоматично: за день до дати чеку.'}
 if(view==='travel'){prepareMonthly();const t=state.travel,r=fuelMetrics(t),v=(x,u='')=>x===undefined||x===null||!Number.isFinite(x)?'—':num(x)+u;
  const kt=$('#km-total');if(kt)kt.innerHTML=`${r.error||r.total===undefined?'—':num(r.total)} <small>км</small>`;
  const st=$('#fuel-status');if(st){st.className='hero-status '+(r.error?'warn':'ok');st.innerHTML=r.error?esc(!Number(t.refill)&&Number(t.startFuel)<=Number(t.endTarget)?'Введіть, скільки пального залили':r.error):`${icon('check')}Витрачено ${num(t.liters)} л · норма ${num(t.rate)} л/100 км`}
  const range=$('#tank-range');if(range){const max=tankMax();if(+range.max!==max)range.max=max;if(document.activeElement!==range)range.value=t.endTarget;range.style.setProperty('--p',Math.min(100,Number(t.endTarget)/max*100)+'%')}
  const ri=$('#refill-input');if(ri)ri.style.width=(ri.value||'0').length+.6+'ch';const tv=$('#tank-value');if(tv)tv.textContent=num(t.endTarget)+' л';
  const th=$('#tank-hint');if(th)th.textContent=r.error?'':`Менше в баку — більше кілометрів: кожен літр ≈ ${num(round(100/Number(t.rate||1),1))} км`;
  const fs=$('#fuel-stats');if(fs)fs.innerHTML=[['На виїзді',v(Number(t.startFuel),' л')],['Залито',v(Number(t.refill),' л')],['Витрачено',v(Number(t.liters),' л')],['Одометр виїзд',v(Number(t.odometer))],['Одометр приїзд',v(r.endOdo)],['Пробіг',v(r.total,' км')],['За нормою',v(r.normFuel,' л')],['Фактично',v(r.actualRate,' л/100')],['Відхилення',v(r.deviation,'%')]].map(([a,b])=>`<div><span>${a}</span><b>${b}</b></div>`).join('');
  const rc=$('#real-comparison');if(rc)rc.innerHTML=`<p class="hint">${r.realDifference===null?'Реальний пробіг не потрапляє до друкованого листа.':`Реальний − звітний: ${num(r.realDifference)} км (${num(r.realPercent)}%). Витрата за реальним: ${r.realRate===null?'—':num(r.realRate)} л/100 км.`}</p>`;
  const last=$('[data-last-km]');if(last)last.value=r.rows?.at(-1)?.km??0}
}
function eventErrors(budget){const e=state.event;let errors=[];if(!e.venue.trim())errors.push('назву закладу');if(!validDate(e.date))errors.push('дату круглого столу');if(!eventDates(e).orderDate)errors.push('дату чеку');if(!e.person.trim())errors.push('відповідальну особу');if(!e.products.length)errors.push('хоча б один препарат');if(budget&&(!e.items.length||e.items.some(r=>!r.name.trim()||!(Number(r.qty)>0)||Number(r.price)<0||!Number.isFinite(Number(r.price)))))errors.push('коректні позиції кошторису');return errors}
function travelErrors(){const t=state.travel,r=travelCalc(t);if(r.error)return r.error;if([t.odometer,t.startFuel,t.endTarget].some(n=>!Number.isFinite(Number(n))||Number(n)<0))return 'Залишок, заправка й одометр мають бути невід’ємними.';if(!t.driver.trim()||!t.car.trim()||!t.plate.trim())return 'Заповніть водія, автомобіль і державний номер.';if(!t.from||!t.to||t.to<t.from)return 'Перевірте початок і кінець періоду.';if(t.rows.some(r=>!r.route.trim()||!r.date||r.date<t.from||r.date>t.to))return 'Заповніть маршрути й дати всіх поїздок у межах періоду.';return ''}
function documentHtml(type){const e=state.event,p=state.profile,d=eventDates(e).orderDate,val=s=>esc(s||'________________');if(type==='order')return `<article class="paper order"><h1>Н А К А З №${val(e.number)}</h1><div class="order-date"><span>м. ${val(e.city)}</span><span>${longDate(d)}</span></div><div class="order-subject">«Про організацію круглого столу<br>у ${val(e.venue)}»</div><p class="command">Наказую:</p><p>${val(e.person)} провести круглий стіл ${date(e.date)} року у ${val(e.venue)} по препаратах: ${val(e.products.join(', '))}</p><p class="order-point">1. &nbsp; Скласти кошторис.</p><p>Підстава: Розпорядження керівника.</p><div class="order-sign"><span>${val(p.position)}<br>${val(p.company)}</span><span>${val(p.head)}</span></div></article>`;if(type==='budget'){const total=money(costTotal(e.items));return `<article class="paper budget"><h1>К О Ш Т О Р И С</h1><p class="budget-subject">Про організацію круглого столу у ${val(e.venue)}</p><div class="amount-line">${total}</div><div class="amount-hint">( сума витрат подано в гривнях)</div><table><thead><tr><th>№</th><th>Опис затрат</th><th>Сума</th></tr></thead><tbody>${e.items.map((r,i)=>`<tr><td>${i+1}</td><td>${val(r.name)}</td><td class="amount">${money(r.qty*r.price)}</td></tr>`).join('')}<tr><td>&nbsp;</td><td></td><td></td></tr><tr><td>&nbsp;</td><td></td><td></td></tr><tr><td></td><td>Всього</td><td class="amount">${total}</td></tr></tbody></table><p class="budget-date">дата: ${date(d)}</p><p class="budget-sign">${val(p.position)}:__________________ ${val(p.budgetHead)}</p></article>`}const t=state.travel,r=travelCalc(t);return travelTemplate(t,r)}
function fitPreview(){const box=$('#full-preview');box.querySelectorAll('.preview-scale').forEach(el=>{const doc=el.firstElementChild;el.style.zoom=1;const w=doc.offsetWidth;el.style.zoom=Math.min(1,(box.clientWidth-24)/w)})}
function preview(type){docType=type;const dlg=$('#preview-dialog');$('#preview-switch').innerHTML=type==='travel'?'':`<div class="segmented small"><button data-doc="order" class="${type==='order'?'selected':''}">Наказ</button><button data-doc="budget" class="${type==='budget'?'selected':''}">Кошторис</button></div>`;const html=documentHtml(type);$('#full-preview').innerHTML=type==='travel'?html.split(/(?=<article)/).filter(Boolean).map(a=>`<div class="preview-scale">${a}</div>`).join(''):`<div class="preview-scale">${html}</div>`;if(!dlg.open)dlg.showModal();requestAnimationFrame(fitPreview)}
window.addEventListener('resize',()=>{if($('#preview-dialog').open)fitPreview()});
function printDoc(type,both=false){if(type==='travel'){const err=travelErrors();if(err)return toast(err)}else{const errors=eventErrors(type==='budget'||both);if(errors.length)return toast('Заповніть: '+errors.join(', ')+'.')}$('#page-style').textContent=`@page { size: ${type==='travel'?'A5':'A4'} portrait; margin: 0; }`;$('#print-root').innerHTML=both?documentHtml('order')+documentHtml('budget'):documentHtml(type);document.body.classList.add('printing');window.print()}
window.addEventListener('afterprint',()=>document.body.classList.remove('printing'));
function storeReport(type){const errors=type==='event'?eventErrors(true).join(', '):travelErrors();if(errors)return toast(type==='event'?'Заповніть: '+errors:errors);const copy=structuredClone(type==='event'?state.event:state.travel);state.archive.push({id:crypto.randomUUID(),type,title:type==='event'?copy.venue:copy.driver,date:type==='event'?copy.date:copy.from,data:copy,profile:structuredClone(state.profile)});save();toast(storageOK?'Звіт збережено в архіві.':'Не вдалося зберегти. Завантажте резервну копію.');render()}
function backup(){const blob=new Blob([JSON.stringify(state,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`zvit-backup-${today()}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function validBackup(s){const str=x=>typeof x==='string'&&x.length<2000,arr=x=>Array.isArray(x)&&x.length<500,num=x=>Number.isFinite(Number(x))&&Number(x)>=0;const event=e=>e&&['venue','date','number','city','person'].every(k=>str(e[k]))&&(e.receiptDate===undefined||(str(e.receiptDate)&&(e.receiptDate===''||validDate(e.receiptDate))))&&arr(e.products)&&e.products.every(str)&&arr(e.items)&&e.items.every(r=>str(r.name)&&num(r.qty)&&num(r.price));const travel=t=>t&&['driver','car','plate','from','to'].every(k=>str(t[k]))&&['liters','rate','startFuel','refill','odometer'].every(k=>num(t[k]))&&(t.endTarget===undefined||num(t.endTarget))&&(t.adjustmentKm===undefined||Number.isFinite(Number(t.adjustmentKm)))&&arr(t.rows)&&t.rows.length>0&&t.rows.every(r=>str(r.date)&&str(r.route)&&num(r.km));const profile=p=>p&&['company','head','budgetHead','position'].every(k=>str(p[k]));return s?.version===1&&validDirectory(s.clinics,'clinics')&&validDirectory(s.representatives,'representatives')&&event(s.event)&&travel(s.travel)&&profile(s.profile)&&arr(s.products)&&s.products.every(str)&&arr(s.archive)&&s.archive.every(r=>str(r.id)&&/^[a-zA-Z0-9-]+$/.test(r.id)&&str(r.title)&&str(r.date)&&profile(r.profile)&&(r.type==='event'?event(r.data):r.type==='travel'&&travel(r.data)))}
async function install(){if(deferredInstall){await deferredInstall.prompt();deferredInstall=null}else{toast('iPhone: Safari → Поділитися → На початковий екран. Android: меню → Встановити застосунок.')}}

/* ---------- Події ---------- */
document.addEventListener('click',async ev=>{const el=ev.target.closest('button');if(!el)return;const ds=el.dataset;
 if(ds.ckind){contactKind=ds.ckind;render();return}
 if(ds.editContact){const kind=ds.contactKind;contactDrafts[kind]={...state[kind].find(r=>r.id===ds.editContact)};render();window.scrollTo(0,0);document.querySelector(`[data-directory="${kind}"]`)?.focus();return}
 if(ds.removeContact){const kind=ds.contactKind;if(confirm('Видалити запис із довідника? Дані у звітах залишаться.')){state[kind]=state[kind].filter(r=>r.id!==ds.removeContact);if(contactDrafts[kind].id===ds.removeContact)contactDrafts[kind]=emptyContact(kind);save();render()}return}
 if(ds.view){go(ds.view);return}
 if(ds.doc){preview(ds.doc);return}
 if(ds.product){const a=state.event.products;a.includes(ds.product)?a.splice(a.indexOf(ds.product),1):a.push(ds.product);save();render();return}
 if(ds.removeItem!==undefined){state.event.items.splice(+ds.removeItem,1);save();render();return}
 if(ds.removeTrip!==undefined&&state.travel.rows.length>1){state.travel.rows.splice(+ds.removeTrip,1);save();render();return}
 if(ds.stepTrip!==undefined){const r=state.travel.rows[+ds.stepTrip];r.km=Math.max(0,round(Number(r.km)+Number(ds.step)));save();render();return}
 if(ds.deleteArchive){if(confirm('Видалити збережений звіт? Перед видаленням можна завантажити резервну копію.')){state.archive=state.archive.filter(r=>r.id!==ds.deleteArchive);save();render()}return}
 const a=ds.action;if(!a)return;
 if(a==='logout'){try{await logout()}catch(e){toast(e.message)}return}
 if(a==='accounts'){await showAccounts();return}
 if(a==='create-account'){await createAccount();return}
 if(a==='change-password'){await changePassword();return}
 if(a==='toggle-account'||a==='reset-account-password'){await editAccount(a,ds.id);return}
 if(a.startsWith('open-')&&!['open-signer','open-password'].includes(a)){const r=state.archive.find(r=>r.id===a.slice(5));if(r&&confirm('Відкрити звіт замість поточної чернетки? Незбережені в архіві зміни чернетки буде замінено.')){state[r.type==='event'?'event':'travel']=structuredClone(r.data);state.profile=structuredClone(r.profile);state.travel.endTarget??=state.travel.startFuel;state.travel.adjustmentKm??=0;save();go(r.type)}return}
 switch(a){
  case 'back':back();break;
  case 'month-prev':case 'month-next':await setMonth(shiftMonth(state.travel.from,a==='month-prev'?-1:1));break;
  case 'tank-minus':case 'tank-plus':{const t=state.travel;t.endTarget=Math.max(0,round(Number(t.endTarget)+(a==='tank-plus'?1:-1)));prepareMonthly();save();updateDerived();break}
  case 'open-signer':go('signer');break;
  case 'open-password':go('password');break;
  case 'contacts-clinics':case 'contacts-representatives':contactKind=a.slice(9);if(!state[contactKind].length)contactForm[contactKind]=true;go('contacts');break;
  case 'add-contact':contactForm[contactKind]=true;render();document.querySelector(`[data-directory="${contactKind}"]`)?.focus();break;
  case 'manage-contacts':contactKind='clinics';go('contacts');break;
  case 'fuel-open':{const row=fuelRows[Number(ds.index)];if(row){state.travel={...defaults().travel,...structuredClone(row)};state.travel.refill=travelCalc(row).refill;state.travel.fuelMode='filled';save();docType='travel';if(history.state?.view==='fuel'&&history.state?.pushed)history.back();else go('travel');window.scrollTo(0,0)}break}
  case 'save-month':try{await saveFuel();save();toast('Дані місяця збережено на сервері.');}catch(e){toast(e.message)}break;
  case 'fuel-analytics':await loadFuel();go('fuel');break;
  case 'fuel-import':try{await api('/api/fuel/import',{});await loadFuel();render();toast('Історію Excel імпортовано.');}catch(e){toast(e.message)}break;
  case 'fuel-previous':await previousFuel();break;
  case 'remember-clinic':rememberContact('clinics');break;
  case 'remember-representative':rememberContact('representatives');break;
  case 'save-clinics':case 'save-representatives':saveContact(a.slice(5));break;
  case 'cancel-clinics':case 'cancel-representatives':{const k=a.slice(7);contactDrafts[k]=emptyContact(k);contactForm[k]=false;render();break}
  case 'preset-seat':case 'preset-vw':{const seat=a==='preset-seat';Object.assign(state.travel,{rate:seat?10:9,startFuel:seat?20:25,endTarget:seat?20:25,odometer:seat?12675.7:80238,car:seat?'SEAT':'VW',adjustmentKm:0,basis:seat?'seat · вересень 2026 · D21/F21/G21':'vw · жовтень 2024 · D53/F53/G53'});fuelLoaded=false;save();render();await previousFuel();break}
  case 'next-period':{try{await saveFuel()}catch(e){toast(e.message);break}const result=travelCalc(state.travel);const next=new Date(state.travel.from+'T12:00:00Z');next.setUTCMonth(next.getUTCMonth()+1);const bounds=monthBounds(next.toISOString().slice(0,7));Object.assign(state.travel,{...bounds,liters:0,refill:0,realKm:'',fuelMode:'filled',startFuel:result.endFuel,endTarget:result.endFuel,odometer:result.endOdo,adjustmentKm:0,autoBasisMonth:bounds.from.slice(0,7),basis:'попередній збережений місяць',rows:[{date:bounds.from,route:'',km:0}]});save();render();window.scrollTo(0,0);toast('Місяць збережено. Відкрито наступний місяць.');break}
  case 'new-event':if(confirm('Очистити форму? Дані поточної події буде видалено. Якщо вони потрібні, спершу натисніть «В архів».')){state.event=defaults().event;save();render()}break;
  case 'add-product':{const p=$('#new-product').value.trim();if(!p)return toast('Введіть назву препарату.');if(!state.products.includes(p))state.products.push(p);if(!state.event.products.includes(p))state.event.products.push(p);save();render();break}
  case 'add-item':state.event.items.push({name:'',qty:1,price:0});save();render();document.querySelector(`[data-item="${state.event.items.length-1}"]`)?.focus();break;
  case 'add-trip':{if(state.travel.rows.length>=5){toast('У бланку є 5 рядків завдань. Додаткові деталі можна внести в особливі відмітки.');break}const r=travelCalc(state.travel);if(r.rows)state.travel.rows=r.rows.map(({fuel,...row})=>row);state.travel.rows.push({date:state.travel.to,route:'',km:0});save();render();break}
  case 'split-trips':{const r=travelCalc(state.travel);if(r.total===undefined)return toast(r.error);state.travel.rows.forEach(row=>row.km=Math.floor(r.total/state.travel.rows.length*100)/100);save();render();break}
  case 'save-event':storeReport('event');break;
  case 'save-travel':try{await saveFuel();storeReport('travel');}catch(e){toast(e.message)}break;
  case 'preview':preview(docType==='travel'?'order':docType);break;
  case 'travel-preview':preview('travel');break;
  case 'print':printDoc(docType);break;
  case 'print-both':printDoc('order',true);break;
  case 'print-travel':printDoc('travel');break;
  case 'backup':backup();break;
  case 'restore':$('#restore-file').click();break;
  case 'install':install();break}});
document.addEventListener('input',ev=>{const el=ev.target,ds=el.dataset;if(ds.directory){contactDrafts[ds.directory][ds.contactField]=el.value;return}if(el.id==='archive-search'){$('#archive-list').innerHTML=archiveList(el.value);return}if(ds.key){const [obj,key]=ds.key.split('.');state[obj][key]=key==='realKm'&&el.value===''?'':el.type==='number'||el.type==='range'?Number(el.value):el.value;if(obj==='travel')prepareMonthly();save();updateDerived()}if(ds.item!==undefined){state.event.items[+ds.item][ds.prop]=ds.prop==='name'?el.value:Number(el.value);save();updateDerived()}if(ds.trip!==undefined&&!el.readOnly){state.travel.rows[+ds.trip][ds.prop]=ds.prop==='km'?Number(el.value):el.value;save();updateDerived()}});
document.addEventListener('change',async ev=>{if(ev.target.hasAttribute('data-fuel-month')){const bounds=monthBounds(ev.target.value);if(!bounds)return toast('Виберіть коректний місяць.');Object.assign(state.travel,bounds);state.travel.rows.forEach(row=>row.date=bounds.from);state.travel.refill=0;state.travel.realKm='';state.travel.adjustmentKm=0;delete state.travel.autoBasisMonth;await previousFuel();save();render();return;}if(ev.target.dataset.key==='travel.car'||ev.target.dataset.key==='travel.plate'){await previousFuel();return;}const picker=ev.target.dataset.contactPicker;if(picker){const target=ev.target.dataset.target||'event';if(ev.target.value)applyContact(state,picker,ev.target.value,target);else delete state[target][picker==='clinics'?'clinicId':'representativeId'];save();render();return}if(ev.target.id!=='restore-file')return;try{const f=ev.target.files[0];if(!f)return;if(f.size>5000000)throw Error('Файл завеликий.');const incoming=JSON.parse(await f.text());if(!validBackup(incoming))throw Error('Невірний формат резервної копії.');if(confirm('Замінити всі поточні дані даними з резервної копії?')){state=migrateDirectories(incoming);state.travel.endTarget??=state.travel.startFuel;state.travel.adjustmentKm??=0;save();render();toast('Дані відновлено.')}}catch(e){toast('Не вдалося відновити: '+e.message)}});
$('#close-preview').onclick=()=>$('#preview-dialog').close();$('#dialog-print').onclick=()=>printDoc(docType);
window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();deferredInstall=e});if('serviceWorker'in navigator)navigator.serviceWorker.register('./sw.js').catch(()=>{});
history.replaceState({view},'');render();if(!storageOK)toast('Локальне збереження недоступне. Робіть резервні копії.');
